window.DOSIK=window.DOSIK||{};DOSIK["gs_tax"]={"1":[{"t":"table","title":"납세의무와 신탁","head":["항목","내용"],"rows":[["사업자","영리든 비영리든 관계없이 사업상 독립적으로 재화·용역을 공급하는 자이고, 국가·지방자치단체·지방자치단체조합과 법인격 없는 사단·재단도 포함된다"],["재화를 수입하는 자","사업자인지와 관계없이 납세의무가 있다"],["사업자등록·거래징수","하지 않았어도 납세의무는 생긴다"],["청산 중인 법인","사실상 사업을 계속하면 납세의무가 있다"],["위탁매매·대리인 매매","위탁자 또는 본인이 공급한 것으로 보고, 위탁자·본인을 알 수 없을 때만 수탁자·대리인이 공급한 것으로 본다"],["신탁재산 관련 재화","수탁자 명의로 공급하면 수탁자가, 위탁자 명의로 공급하면 위탁자가 납세의무를 진다"],["공동수탁자","연대납부 의무가 있다"],["신탁 종료·수탁자 변경","위탁자에게 이전하거나 수탁자가 바뀌어 이전하는 것은 재화의 공급이 아니다"]]},{"t":"table","title":"재화·용역·과세기간","head":["항목","내용"],"rows":[["재화","재산 가치가 있는 물건과 권리이고, 전기·가스·열 등 관리할 수 있는 자연력도 재산 가치가 있어야 재화다"],["용역","재화 외에 재산 가치가 있는 모든 역무와 행위다"],["과세사업자","일반과세자와 간이과세자로 나뉜다"],["간이과세자","직전 연도 공급대가가 1억400만원에 미달하는 개인사업자다"],["일반과세자 과세기간","1월 1일부터 6월 30일까지가 제1기, 7월 1일부터 12월 31일까지가 제2기이다"],["간이과세자 과세기간","1월 1일부터 12월 31일까지다"],["신규사업자","사업 개시일부터, 개시일 전에 등록을 신청했으면 신청한 날부터 과세기간이 시작한다"],["폐업","과세기간 개시일부터 폐업일까지이고, 합병 소멸법인의 폐업일은 합병법인의 변경등기일 또는 설립등기일이다"],["간이과세자가 일반과세자로 바뀌는 해","1월 1일부터 6월 30일까지가 간이과세자 과세기간이다"],["일반과세자가 간이과세자로 바뀌면","7월 1일부터 12월 31일까지가 간이과세자 과세기간이다"],["간이과세 포기","개시일부터 포기 신고일이 속하는 달의 마지막 날까지가 간이과세자, 그 다음 달 1일부터가 일반과세자 과세기간이다"]]},{"t":"table","title":"사업장과 납세지","head":["항목","내용"],"rows":[["사업장","거래의 전부 또는 일부를 하는 고정된 장소이고, 없으면 주소 또는 거소를 사업장으로 한다"],["부동산임대업","부동산 등기부상 소재지가 원칙이지만 부동산상의 권리만 대여하거나 국가·지방자치단체가 임대하면 업무총괄 장소다"],["직매장","사업장이다"],["사업장이 아닌 곳","신고된 하치장과 박람회 임시사업장, 제품 포장·충전만 하는 장소는 사업장이 아니다"],["무인자동판매기 사업","업무총괄 장소 외에 추가 등록할 수 없다"],["사업자의 납세지","각 사업장의 소재지다"],["사업자 단위 과세 사업자","본점 또는 주사무소 소재지가 납세지이고 지점은 될 수 없다"],["재화를 수입하는 자","관세법에 따라 수입을 신고하는 세관의 소재지이고, 수입재화의 부가가치세는 세관장이 징수한다"]]},{"t":"table","title":"사업자등록과 사업자 단위 과세","head":["항목","내용"],"rows":[["사업자등록 신청","사업 개시일부터 20일 이내에 사업장 관할 세무서장에게 신청한다"],["신규사업자","개시일 전에도 신청할 수 있으며 다른 세무서장에게 신청해도 관할 세무서장에게 한 것으로 본다"],["상호 변경","신고일 당일 재발급한다"],["대표자·업종·공동사업자 지분·상속 명의 변경과 사업장 이전","2일 이내에 재발급한다"],["미등록 가산세","사업 개시일부터 등록 신청일의 직전일까지 공급가액의 1퍼센트이다"],["납세관리인","개인이 6개월 이상 국외에 체류하려면 정한다"],["사업자 단위 과세","사업장이 둘 이상이면 본점 또는 주사무소 관할 세무서장에게 사업자 단위로 등록할 수 있고 등록번호는 하나다"],["변경","적용받을 과세기간 개시 20일 전까지 신청한다"],["포기","다음 과세기간부터 사업장별로 신고·납부하거나 총괄 납부를 신청한다"],["주사업장 총괄 납부","납부만 총괄하고 신고·결정은 사업장별로 하며 법인은 본점 또는 지점, 개인은 주사무소를 주된 사업장으로 한다"]]}],"2":[{"t":"table","title":"재화·용역의 공급","head":["항목","내용"],"rows":[["재화의 공급","매매·가공·교환·현물출자 등 계약상·법률상 원인에 따른 재화의 인도·양도가 재화의 공급이고, 특허권·저작권 같은 권리의 양도도 재화의 공급이다"],["가공","주요자재의 전부 또는 일부를 부담하고 가공해 새 재화를 만들어 인도하면 재화의 공급이다"],["재화의 공급이 아닌 것","질권·저당권·양도담보 목적의 제공, 민사집행법상 경매, 국세징수법상 공매, 수용 대가 수령, 사업용 자산 물납, 조달청 창고증권 양도로서 임치물 반환이 없는 것, 신탁 종료나 수탁자 변경에 따른 이전"],["공급의제","매입세액이 공제된 자기생산·취득재화를 면세사업에 쓰거나, 개인적 목적으로 쓰거나, 고객에게 증여하거나, 폐업 때 남아 있으면 재화의 공급으로 본다"],["공급이 아닌 것","작업복·작업모·작업화 제공, 견본품의 무상 인도, 특별재난지역 증여, 주된 거래 대가에 포함된 고객 증여"],["판매 목적 다른 사업장 반출","공급이지만 사업자 단위 과세 사업자와 주사업장 총괄 납부 사업자는 제외하고, 총괄 납부 사업자가 세금계산서를 발급해 신고하면 공급으로 본다"],["용역의 공급","역무 제공과 시설물·권리 등 재화를 사용하게 하는 것이다"],["용역으로 보는 것","건설업자가 자재를 부담하는 건설, 주요자재를 전혀 부담하지 않는 단순 가공, 산업상·상업상·과학상 정보 제공"],["용역의 공급이 아닌 것","고용관계에 따른 근로 제공은 용역의 공급이 아니고, 전·답·과수원·목장용지·임야·염전 임대업은 과세 용역에서 제외된다"],["재화의 수입","외국에서 도착해 수입신고 수리 전인 물품과 외국 선박이 공해에서 잡은 수산물을 국내에 반입하면 재화의 수입이다"],["수입이 아닌 것","수출신고 수리 후 선적되지 않은 물품을 보세구역에서 반입하는 것은 수입이 아니고, 보세구역에는 자유무역지역이 포함된다"],["부수 공급","주된 공급에 통상 포함되는 부수 재화·용역은 주된 공급에 포함되고, 우연히·일시적으로 공급되거나 필연적으로 생기는 재화는 별도 공급이되 과세·면세 여부는 주된 사업을 따른다"]]},{"t":"table","title":"공급시기","head":["거래","공급시기"],"rows":[["현금·외상판매","인도되거나 이용 가능하게 되는 때"],["상품권","현물과 교환되어 실제 인도되는 때"],["조건부·기한부 판매","조건이 성취되거나 기한이 지나 확정되는 때"],["무인판매기","현금을 꺼내는 때"],["장기할부·완성도기준·중간지급조건부와 계속 공급하는 전력 등","대가의 각 부분을 받기로 한 때이며, 중간지급조건부는 계약금 다음 날부터 인도일까지 6개월 이상인 경우다"],["폐업 전 공급분","공급시기가 폐업일 후에 오면 폐업일이 공급시기다"],["내국물품 수출","선(기)적일"],["외국인도수출과 위탁가공 원료 무상반출","외국에서 인도되는 때"],["위탁판매수출","공급가액이 확정되는 때"],["무환수출","외국에서 판매되는 때"],["공급시기 전 대가 수령","공급시기 전에 대가를 받고 세금계산서를 발급하거나, 발급 후 7일 이내에 대가를 받으면 발급한 때가 공급시기다"],["7일이 지나 받는 경우","청구시기와 지급시기 사이가 30일 이내이거나 공급시기가 같은 과세기간에 오면 7일이 지나 받아도 발급일이 공급시기다"]]},{"t":"table","title":"공급장소와 영세율","head":["항목","내용"],"rows":[["재화의 공급장소","재화의 이동이 필요하면 이동이 개시되는 장소, 필요 없으면 공급시기에 재화가 있는 장소다"],["용역의 공급장소","역무가 제공되거나 시설물·권리가 사용되는 장소다"],["국제운송","비거주자·외국법인의 국제운송은 여객이 탑승하거나 화물이 적재되는 장소"],["전자적 용역","국외사업자의 전자적 용역은 공급받는 자의 사업장·주소지·거소지가 공급장소다"],["영세율 대상","수출, 국외 제공 용역, 선박·항공기의 외국항행용역(상업서류 송달용역 포함), 내국신용장·구매확인서에 의한 공급(금지금 제외), 국내사업장 없는 외국법인에 대한 일정 용역으로서 외국환은행에서 원화로 받는 것, 외교공관에 대한 공급, 외국인 관광객 관광알선용역"],["수출재화임가공용역","부가가치세를 별도로 적은 세금계산서를 발급하면 영세율을 적용하지 않는다"],["비거주자·외국법인","상호주의에 따라 적용하고, 첨부서류를 내지 않은 부분은 예정·확정신고로 보지 않는다"]]},{"t":"vs","title":"면세와 과세","cols":[{"name":"면세","items":["미가공식료품(단순 혼합 포함), 토지, 도서·정기간행물(광고 제외), 우표(수집용 제외), 주택 임대(규모 무관), 의료보건 용역(안마사·장의·산후조리원 포함, 비급여 탈모치료술 제외), 인가 학교·산학협력단 교육, 시내버스 운송은 면세다"]},{"name":"과세","items":["무도학원·자동차운전학원 교육, 은행업 소프트웨어 판매, 소포 방문접수 배달, 삭도·시외우등고속버스 운송, 골동품은 과세다"]},{"name":"면세포기","items":["영세율 대상인 면세 재화와 학술연구단체의 실비·무상 공급은 면세포기를 신고할 수 있다","포기하면 신고일부터 3년간 면세를 받지 못하며 이후 면세적용신고서를 낸다"]}]}],"3":[{"t":"vs","title":"공급가액","cols":[{"name":"공급가액에 포함","items":["장기할부 이자상당액","대가로 받은 운송비","공급과 직접 관련된 국고보조금·공공보조금","수입금액에 계상한 봉사료"]},{"name":"포함하지 않음","items":["연체이자","에누리","약정기일 전 결제 할인액","도달 전 파손·멸실 재화","환입 재화","반환 조건 용기대금·포장비","공급과 직접 관련 없는 보조금","자기적립마일리지 결제분"]},{"name":"공급가액에서 빼지 않음","items":["공급받는 자에게 지급하는 장려금과 대손금은 공급가액에서 빼지 않는다"]}]},{"t":"table","title":"특수한 공급가액","head":["항목","공급가액·과세표준"],"rows":[["금전 외의 대가","자기가 공급한 재화·용역의 시가"],["특수관계인에게 부당하게 낮은 대가로 공급","시가가 공급가액이다"],["특수관계인에게 무상으로 제공한 용역","부동산 임대용역만 과세한다"],["폐업 잔존재화","시가"],["감가상각자산","취득가액에 건물·구축물은 1과세기간마다 5%, 그 밖에는 25%씩 줄인 금액이다"],["토지와 건물을 함께 공급","건물 등의 실지거래가액이 공급가액이고, 구분이 불분명하거나 안분액과 100분의 30 이상 차이 나면 감정평가가액, 기준시가, 장부가액 순으로 안분한다"],["재화 수입","관세의 과세가격에 관세·개별소비세·주세·교육세·농어촌특별세·교통·에너지·환경세를 더한 금액이고 담배소비세는 넣지 않는다"],["공통사용 재화를 공급","직전 과세기간의 과세공급가액 비율로 과세표준을 정한다"]]},{"t":"table","title":"매입세액 공제","head":["항목","내용"],"rows":[["공제하지 않는 매입세액","세금계산서 미수취·필요적 기재사항 누락, 사업과 직접 관련 없는 지출, 개별소비세법상 자동차의 구입·임차·유지(운수업·자동차판매·임대·운전학원 등 영업용 제외), 기업업무추진비, 면세사업 관련, 토지 관련(형질변경·부지조성·건물 철거비 포함), 등록 전 매입세액"],["등록 전 매입세액","등록 전이라도 공급시기가 속하는 과세기간이 끝난 후 20일 이내에 등록을 신청하면 그 과세기간 기산일까지 역산한 기간의 매입세액은 공제한다"],["세금계산서 공제","공급시기 후라도 확정신고기한까지 받은 세금계산서와 기재 착오가 있어도 거래사실이 확인되는 세금계산서는 공제한다"],["겸영사업자의 매입세액","실지귀속에 따르고, 구분할 수 없는 공통매입세액만 당기 공급가액 비율로 안분한다"],["전부 공제","면세공급가액이 5퍼센트 미만(공통매입세액 500만원 이상 제외), 공통매입세액 합계가 5만원 미만, 신규사업자가 그 과세기간에 매입·매각한 재화는 전부 공제한다"],["감가상각자산 재계산","면세비율이 취득 또는 직전 재계산 과세기간보다 5퍼센트 이상 차이 나면 확정신고 때 재계산한다"],["면세사업용 자산 전용","과세사업에 전용하면 경과기간만큼 줄인 매입세액을 공제한다"],["의제매입세액","면세농산물을 원재료로 과세 재화를 공급하면 매입가액에 공제율을 곱해 공제한다"],["공제율","제조업 중소기업·개인은 104분의 4, 그 밖의 법인은 102분의 2, 법인 음식점은 106분의 6이다"],["수입 농산물","관세의 과세가격이 매입가액이다"],["면세를 포기하고 영세율","공제하지 않으며 예정신고 때도 공제한다"]]},{"t":"table","title":"대손·세금계산서·신고·간이과세","head":["항목","내용"],"rows":[["대손세액","대손금액의 110분의 10이고 공급일부터 10년이 지난 날이 속하는 과세기간의 확정신고기한까지 확정된 대손에 대해 확정신고 때만 공제한다"],["세금계산서 기재사항","필요적 기재사항은 공급자 등록번호·성명, 공급받는 자 등록번호, 공급가액과 세액, 작성연월일이고 단가·수량·공급연월일은 임의적 기재사항이다"],["전자세금계산서","법인과 직전 연도 공급가액(면세 포함) 8천만원 이상 개인은 발급하고 발급일의 다음 날까지 국세청장에게 전송한다"],["1역월 합계분","다음 달 10일까지 발급할 수 있다"],["매입자발행세금계산서","건당 5만원 이상 거래에 대해 과세기간 종료일부터 1년 이내에 확인을 신청한다"],["신고","예정신고는 예정신고기간이 끝난 후 25일 이내, 확정신고는 과세기간 종료 후 25일 이내에 하고 예정신고에는 가산세를 적용하지 않는다"],["예정고지","개인과 직전 과세기간 공급가액 1억5천만원 미만 법인은 직전 납부세액의 50퍼센트를 예정고지받는다"],["환급","일반 환급은 확정신고기한 후 30일 이내, 영세율·사업설비 취득·재무구조개선계획 이행 중인 조기환급은 신고기한 후 15일 이내에 한다"],["가산세","미등록 가산세는 사업 개시일부터 등록 신청일 직전일까지 공급가액의 1퍼센트, 지연발급과 기재 착오는 1퍼센트, 미발급과 타인 명의 발급·수취는 2퍼센트, 가공 세금계산서는 3퍼센트, 전자발급명세 지연전송은 0.3퍼센트다"],["간이과세자 납부세액","공급대가에 업종별 부가가치율과 10퍼센트를 곱하고, 공급대가 4천800만원 미만이면 납부의무를 면제한다"],["간이과세자 공제","대손세액공제와 의제매입세액공제가 없고, 세금계산서 수취세액공제(공급대가의 0.5퍼센트)는 환급하지 않는다"]]}],"4":[{"t":"table","title":"과세대상과 과세시기","head":["항목","내용"],"rows":[["과세대상","특정 물품, 특정 장소 입장행위, 유흥음식행위, 영업행위에 부과한다"],["납세의무자","과세물품을 제조해 반출하는 자, 보세구역에서 반출하는 자(관세 납세의무자), 과세장소·과세유흥장소·과세영업장소의 경영자다"],["납세의무자가 아닌 자","고급 모피를 일시적으로 판매하는 소비자"],["과세물품 판정","명칭과 관계없이 형태·용도·성질에 따르며 분해·미조립 상태로 반출해도 완제품으로 본다"],["과세시기","제조 물품은 제조장에서 반출할 때, 보세구역 반출 물품은 수입신고를 할 때, 입장·유흥음식·영업행위는 그 행위를 할 때 과세한다"],["반출로 보는 경우","제조장에서 사용·소비되거나 공매·경매·파산절차로 환가되면 반출로 본다"],["반출로 보지 않는 경우","같은 제조장에서 과세물품의 원재료나 시험·연구·검사용으로 쓰는 것, 비과세 석유류의 원재료로 정유공정에 쓰는 것, 기업부설연구소로 옮겨 시험·연구에 쓰는 것, 납세 보증으로 보존하는 것"]]},{"t":"table","title":"세율","head":["대상","세율"],"rows":[["투전기·오락용 사행기구와 수렵용 총포류","물품가격의 100분의 20이다"],["보석·귀금속 제품·고급 모피","1개당 500만원을 넘는 부분에 100분의 20을 매긴다"],["고급 시계·융단·가방","1개당 200만원을 넘는 부분에 100분의 20을 매긴다"],["고급 가구","1조당 800만원 또는 1개당 500만원을 넘는 부분에 100분의 20을 매긴다"],["승용자동차·캠핑용자동차(캠핑용 트레일러 포함)·이륜자동차·전기승용자동차","물품가격의 100분의 5다"],["휘발유","리터당 475원"],["경유","340원"],["등유","90원"],["유연탄","킬로그램당 46원"],["입장행위","경마장 1천원, 경륜·경정장 400원, 투전기 설치 장소 1만원, 골프장 1만2천원, 카지노 5만원(외국인 2천원)"],["유흥음식요금","100분의 10이다"],["잠정세율","기본세율과 탄력세율에 우선한다"]]},{"t":"table","title":"과세표준과 미납세반출","head":["항목","내용"],"rows":[["제조 반출","반출할 때의 가격"],["보세구역 반출","관세의 과세가격과 관세를 합한 금액(기준가격 초과분 과세 물품은 그 초과분)"],["유류","수량"],["유흥음식","요금"],["카지노 영업","총매출액"],["외상·할부","인도한 날의 실제 반출가격"],["무상 반출","반출한 날의 실제 반출가격"],["반출 후 되돌려 주는 금액","있으면 처음 반출가격을 쓴다"],["운송비","거리·방법에 상관없이 같은 금액으로 받거나 낙찰가격에 운송비가 포함돼 있으면 운송비를 포함한다"],["미납세반출","수출할 물품을 다른 장소로 반출, 과세물품 원료로 쓰기 위한 다른 제조장 반출, 위탁 공임만 받고 제조한 물품의 위탁자 창고 반출, 판매장·제조장 이전, 규격 검사용 반출, 박람회 출품 물품의 환입·반출, 내국신용장(제2차 포함)에 의한 수출업자 반출, 승용자동차의 30일 이상 판매장 전시 반출은 개별소비세를 징수하지 않는다"],["반입 사실을 증명하지 못하면","반출자에게서 징수한다"],["반입 전 재해로 멸실","징수하지 않는다"],["위탁 제조 물품을 반입한 위탁자","제조자로 보고 반입지 관할 세무서장에게 반입 사실을 신고한다"],["보세구역 반출","수입신고 수리 전에 세관장의 승인을 받는다"]]},{"t":"vs","title":"면세와 신고·납부","cols":[{"name":"무조건 면세","items":["수출 물품의 용기로 재수입하는 것, 외국 자선·구호기관에 기증하는 물품, 조난 해체재와 장비품, 외국 박람회 출품용 반출, 군함·재외공관에서 송부되는 공용품, 상업용 견본·광고용품, 입국자 휴대품, 거주자가 받는 소액물품은 무조건 면세다","수출신고 수리일부터 6개월 내에 재수입되는 물품으로 원재료에 면제·환급·공제를 받은 사실이 없다고 관할 세무서장이 증명하는 것도 같다","수출과 주한외국군 납품은 수출 및 군납 면세다"]},{"name":"조건부 면세","items":["이화학 실험연구용·공업용 보석, 외국에서 학술연구·교육·자선 목적으로 기증되는 물품, 재수출할 물품으로 관세가 면제되는 것, 외국 무역선·원양어선에서 쓸 연료 외 소모품, 의료용·비료·석유화학공업용 원료 석유류, 산업용·발전용 유연탄, 여객자동차운송사업용 승용자동차는 용도를 지키는 조건으로 면제한다","장애인 승용자동차는 1명당 1대, 500만원을 한도로 하고, 18세 미만 자녀 3명 이상 양육자의 승용자동차는 300만원을 한도로 한다","반입 사실을 증명하지 못하거나 용도 외로 쓰면 징수한다"]},{"name":"신고·납부","items":["제조장 반출 물품과 과세장소 입장행위는 매 분기 다음 달 25일까지(유류·담배는 매월, 다음 달 말일), 유흥음식행위는 매월 다음 달 25일까지, 카지노 영업행위는 다음 해 3월 31일까지 신고한다","과세유흥장소를 폐업하면 폐업일이 속한 달의 다음 달 25일까지 신고·납부하고 외상매출금 잔액도 과세표준에 넣는다","외국인전용판매장 면세 물품을 출국 때 소지하지 않거나 구입할 수 없는 자가 소지하면 개별소비세를 징수하고, 판매장을 대여하면 지정을 취소할 수 있다"]}]}],"5":[{"t":"table","title":"주류의 정의","head":["항목","내용"],"rows":[["주류","알코올분 1도 이상의 음료이다"],["알코올분 도수","섭씨 15도에서 전체용량 100분 중 알코올분의 용량이다"],["주류가 아닌 것","약사법상 의약품으로서 알코올분 6도 미만인 것"],["주정","정제하면 음용할 수 있는 조주정도 포함되며, 주정은 발효주류가 아니다"],["주류의 구분","주정, 발효주류, 증류주류, 기타 주류로 나뉜다"],["밑술","효모를 배양·증식한 재료"],["주조연도","1월 1일부터 12월 31일까지다"]]},{"t":"table","title":"과세표준","head":["항목","내용"],"rows":[["주정·탁주·맥주","반출한 수량이나 수입신고하는 수량이 과세표준이다"],["그 밖의 주류","반출하는 때의 가격이나 수입신고를 하는 때의 가격이다"],["수입 주류의 가격","관세의 과세가격과 관세를 합한 금액이다"],["반출 가격","주세액을 넣지 않고 용기 대금과 포장비용을 넣되, 특별 제조 도자기병과 그 포장물, 전자인식표의 가격은 넣지 않는다"],["선매 방식으로 통상가격보다 낮게 반출","통상가격"],["외상 방식으로 통상가격보다 높게 반출","그 반출가격을 주류 가격으로 한다"],["운송비","거리와 관계없이 같은 운송비를 받으면 운송비를 포함한다"],["상거래 관습상 공제하는 금액","공제하기 전 금액을 가격으로 한다"],["무상 반출로 통상가격을 낼 수 없으면","제조원가에 10퍼센트 이윤을 더한다"],["국군부대 등과의 직접계약","계약금액을 통상가격으로 본다"]]},{"t":"table","title":"세율과 반출·신고","head":["항목","내용"],"rows":[["주정","1킬로리터당 5만 7천원이고 알코올분 95도를 넘는 1도마다 600원을 더한다"],["탁주","1킬로리터당 4만4400원"],["맥주","1킬로리터당 88만5700원"],["탁주·맥주 세율 조정","100분의 30 범위에서 대통령령으로 조정할 수 있다"],["약주·과실주·청주","100분의 30"],["소주·위스키 등 증류주류","100분의 72"],["전통주","일정 반출 수량 이하에 대해 100분의 50 범위에서 경감한다"],["반출로 보는 경우","제조장에서 마시거나, 부가가치세법상 재화의 공급으로 보거나, 공매·경매·파산절차로 환가되면 반출한 것으로 본다"],["신고","반출한 자는 매 분기 반출한 날이 속하는 분기의 다음 달 25일까지 신고한다"],["공매·경매·환가나 보존명령 불이행","반출로 보는 경우는 사유가 생긴 달의 다음 달 말일까지 신고한다"],["수입 납부","수입하는 자는 관할 세관장에게 납부한다"],["환입 공제","변질·품질불량으로 같은 제조자의 제조장에 다시 들어오거나 유통 중 파손·멸실되면 세액을 공제하거나 환급한다"]]},{"t":"vs","title":"면세와 납세담보","cols":[{"name":"면세","items":["수출, 우리나라 주둔 외국군대 납품, 외국에 주둔하는 국군부대 납품, 주한외국공관 납품, 외국 선원 휴게소(안에서 음용하는 것) 납품, 검사 목적 수거, 무형유산 기능보유자가 무형유산 공개에 쓰는 주류, 의약품 원료, 연료용 등 공업용 주정은 면세다","수입 시에는 공관의 공용품, 주한외교관의 자가 소비용 수입, 외국에서 종교단체에 기증한 의식용 주류, 관세가 면제되는 여행자 휴대 주류, 품질불량으로 다시 들어온 수출 주류가 면세다"]},{"name":"면세가 아님","items":["명예영사관 수입분","국내에서 종교단체에 기증한 주류","무형유산 보유자가 판매 목적으로 만든 주류"]},{"name":"납세담보","items":["관할 세무서장은 주세 보전을 위해 필요하면 주류 제조자에게 금액과 기간을 정해 담보를 제공하게 하거나 주세액에 상당하는 가액의 주류를 보존하도록 명할 수 있다","보존 주류의 가격은 통상가격이고, 제조자는 납세보증주류를 처분하거나 반출하지 못한다","담보·보존 기간이 2주조연도 이상이면 매년 1월에 적정성을 조사한다"]}]}],"6":[{"t":"table","title":"과세물품과 납세의무","head":["항목","내용"],"rows":[["목적","교통시설 확충과 대중교통 육성, 에너지·자원 사업, 환경 보전·개선 사업의 재원을 마련하기 위한 목적세다"],["과세물품","휘발유와 유사 대체유류(리터당 475원), 경유와 유사 대체유류(리터당 340원) 두 가지다"],["세율 조정","재원 조달과 수급상 필요하면 100분의 30 범위에서 대통령령으로 조정할 수 있다"],["폐지법률","2026년 1월 2일 폐지법률이 공포되었고, 폐지 시행 전까지는 이 법이 적용된다"],["납세의무자","과세물품을 제조해 반출하는 자, 보세구역에서 반출하는 자(관세 납세의무자), 그 밖에 관세를 징수하는 물품의 관세 납세의무자다"],["과세시기","제조장에서 반출하거나 수입신고를 하는 때 과세한다"],["과세물품이 둘 이상에 해당","특성, 주된 용도 순으로 판정하고 그래도 불분명하면 높은 세율 물품으로 본다"]]},{"t":"table","title":"반출 의제와 신고·납부","head":["항목","내용"],"rows":[["제조로 보는 경우","제조장 밖에서 판매 목적으로 가치를 높이는 첨가 등 가공을 하면 제조로 본다"],["반출로 보는 경우","제조장 안에서 사용·소비되거나, 공매·경매·파산절차로 환가되거나, 제조를 사실상 폐지했을 때 남아 있는 물품은 반출로 본다"],["과세표준","반출하거나 수입신고하는 때의 수량이고, 휘발유는 수송·저장 중 자연감소분을 뺀 수량으로 한다"],["제조 반출자 신고","매월 반출 물품의 수량·세액 등을 적은 신고서를 다음 달 말일까지 제조장 관할 세무서장에게 내고 그 기한 안에 납부한다"],["보세구역 반출자","세관장에게 수입신고를 하면 과세표준을 신고한 것으로 보고 납부는 관세법에 따른다"]]},{"t":"table","title":"담보와 미납세반출","head":["항목","내용"],"rows":[["담보","수입신고 수리 전에 보세구역에서 반출하려면 세액 상당 담보를 제공한다"],["사업자 단위","둘 이상의 제조장이 있으면 사업자 단위로 본점에서 총괄 신고·납부할 수 있고, 사업자 단위 신고는 적용받으려는 달이 시작되기 20일 전까지 한다"],["미납세반출","수출할 물품을 다른 장소로 반출, 위탁 공임만 받고 제조한 물품을 위탁자 창고로 반출, 규격검사용 반출·환입, 품질불량으로 제조장에 반환하는 것은 승인을 받으면 징수하지 않는다"],["반입 사실을 증명하지 못하면","반출자나 수입신고인에게서 징수하고, 반입 전 재해로 멸실되면 징수하지 않는다"],["반입한 자","제조자로 보며 반입한 날이 속하는 달의 다음 달 15일까지 반입 사실을 신고한다"]]},{"t":"vs","title":"면세와 공제·환급","cols":[{"name":"면세","items":["수출과 주한외국군 납품은 면세하고, 주한외국군 면세 물품을 양도하면 양수자에게서 징수한다","주한외교공관과 외교관의 자동차에 쓰는 물품은 상호주의에 따라 면세하고 연도별 면세한도량은 외교부장관이 정한다","외국 자선단체·국가·지방자치단체에 기증하는 것은 무조건 면세다"]},{"name":"조건부 면세","items":["자선·구호기관에 기증되는 것, 재수출 조건 물품, 의료용·비료·농약·석유화학 원료와 외국항행선박·원양어선·항공기용은 조건부 면세이다"]},{"name":"공제·환급·수시부과","items":["세금이 붙은 원재료를 과세물품 제조에 쓰면 그 세액을 공제하고, 수출·군납, 제조장 환입, 의료용 등 원료 사용이면 환급한다","공제·환급은 사유 발생일부터 6개월이 지난 날이 속하는 달의 말일까지 신청하고 가산세는 공제·환급하지 않는다","포탈 우려나 휴업·폐업 때는 수시부과하고, 납세보전 명령 위반은 2천만원 이하 과태료다"]}]}],"7":[{"t":"table","title":"납세의무와 과세문서","head":["항목","내용"],"rows":[["납세의무자","국내에서 재산에 관한 권리의 창설·이전·변경에 관한 계약서나 이를 증명하는 문서를 작성하는 자가 인지세를 낸다"],["공동 작성","2인 이상이 공동으로 작성하면 연대하여 납부한다"],["과세문서 판단","명칭과 관계없이 실질적인 내용에 따라 판단하고 전자문서도 포함하며 통장은 1권마다, 그 밖의 문서는 1통마다 납부한다"],["보완문서","하나의 문서 내용을 다른 문서가 보완해 하나의 계약을 이루면 그 보완문서도 과세문서로 본다"],["보완문서의 예외","신용카드 가입 신청서 같은 계속적·반복적 거래 증서를 보완하는 문서"]]},{"t":"table","title":"소유권 이전 증서 세액","head":["기재금액","세액"],"rows":[["1천만원 초과 3천만원 이하","2만원"],["5천만원 이하","4만원"],["1억원 이하","7만원"],["10억원 이하","15만원"],["10억원 초과","35만원"],["같은 세액표를 쓰는 증서","금융기관과의 금전소비대차 증서, 법정 도급·위임 증서, 무체재산권 등 권리 양도 증서, 골프장·콘도 회원권 입회·양도 증서"],["기재금액이 없으면","기재사항으로 계산하고, 계산할 수 없으면 최저 기재금액으로 본다"]]},{"t":"table","title":"정액 과세문서","head":["문서","세액"],"rows":[["등록 대상 동산 양도 증서","3천원"],["신용카드회원·가맹점 가입 신청서","300원"],["채무증권·지분증권·수익증권","400원"],["예금·적금 증서나 통장과 보험증권","100원"],["시설대여 계약서","1만원"],["상품권과 선불카드","권면금액 1만원 50원, 5만원 이하 200원, 10만원 이하 400원, 10만원 초과 800원"],["모바일 상품권","5만원 초과분부터 과세하며 7일 이내 전액 환불·폐기된 것은 제외한다"]]},{"t":"vs","title":"비과세·납부·확정","cols":[{"name":"비과세문서","items":["국가·지방자치단체가 작성하는 증서, 국고금 취급 증서, 공공사업 기부 증서, 자선·구호단체의 사업 증서, 어음의 인수·보증, 우편전용 물건 증서, 공익사업용 토지를 국가 등에 양도하는 증서는 인지세를 내지 않는다","기재금액 1억원 이하 주택 소유권 이전 증서와 5천만원 이하 금전소비대차 증서도 비과세다","국가 등과 그 밖의 자가 공동 작성해 각각 가지는 문서는 국가 등이 가진 것은 그 밖의 자가, 그 밖의 자가 가진 것은 국가 등이 작성한 것으로 본다"]},{"name":"납부·환급","items":["종이문서용 전자수입인지를 과세문서에 첨부해 내거나 세액을 납부하고 납부 사실을 표시하는 방법으로 낸다","과세문서 작성일이 속하는 달의 다음 달 10일까지 납부하고, 전자조달시스템으로 작성하는 경우 등은 작성일에 납부한다","납부한 뒤 문서를 작성하지 않으면 환급하거나 공제하고, 특허권·상표권 등 양도증서의 인지세는 지식재산처장이 징수해 납부한다"]},{"name":"성립·확정·결정","items":["인지세 납세의무는 과세문서를 작성한 때 성립하고 특별한 절차 없이 그 때 확정된다","납부하지 않았거나 부족하면 관할 세무서장이나 지방국세청장이 결정·경정한다","첨부한 전자수입인지를 재사용하면 조세범 처벌법에 따라 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다"]}]}],"8":[{"t":"table","title":"조세 포탈죄","head":["항목","내용"],"rows":[["조세","조세범 처벌법의 조세는 관세를 제외한 국세다"],["포탈","사기나 그 밖의 부정한 행위로 조세를 포탈하거나 환급·공제를 받으면 2년 이하의 징역 또는 포탈세액등의 2배 이하 벌금이다"],["가중","포탈세액등이 3억원 이상이면서 납부할 세액의 100분의 30 이상이거나 5억원 이상이면 3년 이하의 징역 또는 3배 이하 벌금이다"],["병과·상습범·감경","징역과 벌금을 병과할 수 있고, 상습범은 형의 2분의 1을 가중하며 법정신고기한 후 2년 이내 수정신고나 6개월 이내 기한 후 신고를 하면 감경할 수 있다"],["부정한 행위","이중장부 등 거짓 기장, 거짓 증빙, 장부 파기, 재산 은닉과 거래 조작, 고의적 장부 미작성, 세금계산서 조작 등 부과·징수를 불가능하게 하거나 현저히 곤란하게 하는 적극적 행위다"],["기수 시기","정부가 부과하는 조세는 결정 후 납부기한이 지난 때, 그 밖의 조세는 신고·납부기한이 지난 때 기수가 된다"]]},{"t":"table","title":"조세범의 처벌","head":["범죄","처벌"],"rows":[["세금계산서 미발급·거짓 발급","1년 이하의 징역 또는 공급가액에 부가가치세율을 곱한 세액의 2배 이하 벌금이다"],["가공거래","재화·용역의 공급 없이 세금계산서를 발급하거나 발급받는 가공거래는 3년 이하의 징역 또는 3배 이하 벌금이다"],["알선·중개","이를 알선·중개한 자도 같으며 세무사·공인회계사·변호사가 알선하면 2분의 1을 가중한다"],["가짜석유제품","제조·판매로 포탈하면 5년 이하의 징역 또는 포탈세액의 5배 이하 벌금"],["면세유 부정 유통","3년 이하 징역 또는 5배 이하 벌금"],["무면허 주류 제조·판매","3년 이하 징역 또는 3천만원(주세 상당액의 3배가 더 크면 그 금액) 이하 벌금"],["체납처분 면탈","3년 이하 징역 또는 3천만원 이하 벌금"],["타인 명의 사업자등록","2년 이하 징역 또는 2천만원 이하 벌금"],["원천징수의무자가 징수한 세금을 납부하지 않으면","2년 이하 징역 또는 2천만원 이하 벌금"]]},{"t":"table","title":"고발·공소시효·양벌","head":["항목","내용"],"rows":[["고발","조세범 처벌법 위반은 국세청장, 지방국세청장 또는 세무서장의 고발이 없으면 검사가 공소를 제기할 수 없다"],["공소시효","7년이고, 행위자가 특정범죄가중법 제8조를 적용받으면 법인에 대한 공소시효는 10년이다"],["양벌","법인의 대표자·종업원이 업무에 관해 범칙행위를 하면 행위자와 법인 모두 처벌한다"]]},{"t":"table","title":"성립·확정·제척기간·가산세","head":["항목","내용"],"rows":[["부가가치세 성립","과세기간이 끝나는 때, 수입재화는 세관장에게 수입신고를 하는 때 성립한다"],["개별소비세·주세 성립","제조장에서 반출하거나 판매장에서 판매하는 때, 과세장소 입장·유흥음식행위·영업행위를 하는 때 성립하고, 수입물품은 수입신고를 하는 때 성립한다"],["확정","부가가치세·개별소비세·주세·교통·에너지·환경세는 신고로 확정되고, 인지세는 성립과 동시에 특별한 절차 없이 확정된다"],["부과제척기간","부과할 수 있는 날부터 5년이고, 무신고는 7년, 부정행위로 포탈하거나 환급·공제받으면 10년이다"],["국세징수권","5억원 이상(가산세 제외)이면 10년, 그 밖에는 5년간 행사하지 않으면 소멸한다"],["소멸시효 기산","신고 세액은 법정 신고납부기한의 다음 날, 고지 세액은 고지에 따른 납부기한의 다음 날부터 행사할 수 있다"],["무신고가산세","납부세액의 100분의 20, 부정행위 무신고는 100분의 40이고, 과소신고는 100분의 10, 부정행위 과소신고는 100분의 40이다"],["납부지연가산세","미납세액에 경과일수와 이자율을 곱한 금액과 지정납부기한까지 내지 않은 세액의 100분의 3을 더하며 인지세에는 이 규정을 적용하지 않는다"],["불복","이의신청·심사청구·심판청구는 처분이 있음을 안 날부터 90일 이내에 하고, 이의신청은 30일 이내에 결정한다"]]}]};
